#!/usr/bin/env python3
import os, re, sys, json
from collections import deque

ROOT = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
IMPORT_RE = re.compile(r'^\s*import\s+(AlgebraicJacobian(?:\.[A-Za-z0-9_\']+)*)\s*$')

def mod_to_path(mod):
    return os.path.join(ROOT, mod.replace('.', '/') + '.lean')

def path_to_mod(p):
    rel = os.path.relpath(p, ROOT)
    return rel[:-5].replace('/', '.')

def imports_of(path):
    out = []
    if not os.path.exists(path):
        return out
    with open(path, encoding='utf-8', errors='replace') as f:
        for line in f:
            m = IMPORT_RE.match(line.rstrip('\n'))
            if m:
                out.append(m.group(1))
    return out

def closure(root_mod):
    seen = {root_mod: None}  # mod -> parent
    q = deque([root_mod])
    order = [root_mod]
    while q:
        cur = q.popleft()
        for imp in imports_of(mod_to_path(cur)):
            if imp not in seen:
                seen[imp] = cur
                q.append(imp)
                order.append(imp)
    return seen

def chain(parents, target):
    if target not in parents:
        return None
    ch = []
    cur = target
    while cur is not None:
        ch.append(cur)
        cur = parents[cur]
    return list(reversed(ch))

# direct-import chain via BFS is shortest chain; also compute a DFS chain for readability
ROOT_MOD = "AlgebraicJacobian"
parents = closure(ROOT_MOD)

targets = [
 "AlgebraicJacobian.Picard.DivRepGlobalLift",
 "AlgebraicJacobian.Picard.DivRepKit",
 "AlgebraicJacobian.Picard.JacobianDataCharts",
 "AlgebraicJacobian.Picard.Pic0SigmaSheaf",
]
print("=== Q1-Q4: root closure membership ===")
for t in targets:
    ex = os.path.exists(mod_to_path(t))
    c = chain(parents, t)
    print(f"{t}: file_exists={ex} in_closure={c is not None}")
    if c:
        print("   chain: " + " -> ".join(c))
print()

print("=== Q5: GeometricallyReduced in closure of Pic0SigmaSheaf ===")
sub = closure("AlgebraicJacobian.Picard.Pic0SigmaSheaf")
tgt = "AlgebraicJacobian.Curve.GeometricallyReduced"
c = chain(sub, tgt)
print(f"in_closure={c is not None}")
if c:
    print("   chain: " + " -> ".join(c))
print(f"   (subclosure size = {len(sub)})")
print()

print("=== Q6: orphaned .lean files (not in root closure) ===")
allfiles = []
for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, "AlgebraicJacobian")):
    if '.lake' in dirpath:
        continue
    for fn in filenames:
        if fn.endswith('.lean'):
            allfiles.append(os.path.join(dirpath, fn))
allmods = sorted(path_to_mod(p) for p in allfiles)
inclos = set(parents.keys())
orphans = [m for m in allmods if m not in inclos]
print(f"total .lean under AlgebraicJacobian/ = {len(allmods)}")
print(f"in root closure (excluding root file itself) = {len(inclos)-1}")
print(f"orphans = {len(orphans)}")
for m in orphans:
    print("  " + m.replace('.', '/', 0))
print()

# missing files referenced by imports
missing = [m for m in inclos if m != ROOT_MOD and not os.path.exists(mod_to_path(m))]
print("=== imports referencing nonexistent files ===")
for m in sorted(missing):
    print("  " + m)
print(f"count={len(missing)}")

# also: who imports each orphan (reverse edges among all files)
print()
print("=== reverse-import info for orphans (who imports them, if anyone) ===")
rev = {}
for p in allfiles:
    m = path_to_mod(p)
    for imp in imports_of(p):
        rev.setdefault(imp, []).append(m)
for m in orphans:
    print(f"  {m}: imported_by={rev.get(m, [])}")
